# Figure S2a: descriptive AUC response heatmaps
# Run after 1_import_comp_data.R.
# Uses the final accepted replicate-level AUC data saved locally by the import.
# Displays observed date-level means for RFP and GFP relative to monoculture.
# No additional statistical models or hypothesis tests are fitted.

suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(patchwork)
  library(tibble)
})

# Settings

# Location of the RDS generated by 1_import_comp_data.R.
# Relative to the current working directory; edit if stored elsewhere.
INPUT_FILE <- "analysis_data_rep_all_valid.rds"

SAVE_FIGS2A <- FALSE
OUTPUT_DIR <- file.path("outputs", "figures")

gfp_order <- c("At", "Bp", "Ck", "Pk", "Sl", "Ss")
rfp_order <- c("Pf", "Pu", "Ps", "Ba", "Bb", "Bh")
display_order <- c("Other", "Ba", "Bb", "Bh")

competitor_labels <- c(
  "At" = "Agrobacterium",
  "Bp" = "Brucella",
  "Ck" = "Comamonas",
  "Pk" = "Pseudomonas",
  "Sl" = "Serratia",
  "Ss" = "Staphylococcus"
)

group_labels_plot <- c(
  "Other" = "Non-amoeba-associated",
  "Ba" = "P. agricolaris",
  "Bb" = "P. bonniea",
  "Bh" = "P. hayleyella"
)

# Load accepted AUC data

if (!file.exists(INPUT_FILE)) {
  stop(
    "Cannot find: ", INPUT_FILE, "\n",
    "Current working directory: ", getwd(), "\n",
    "First extract the competition raw-data ZIP, run ",
    "1_import_comp_data.R from the repository root, then run this script.\n",
    "Alternatively, set INPUT_FILE above to the generated RDS location."
  )
}

auc_rep <- readRDS(INPUT_FILE)

need_cols <- c(
  "Date", "RFP_Strain", "RFP_Species6", "GFP_Strain",
  "Normalized_AUC_RFP", "Normalized_AUC_GFP"
)

miss <- setdiff(need_cols, names(auc_rep))
if (length(miss)) {
  stop(
    "The accepted AUC RDS is missing: ",
    paste(miss, collapse = ", ")
  )
}

cat("\nFigure S2a input: ", normalizePath(INPUT_FILE), "\n", sep = "")

# Average technical wells within each accepted experimental date.
# Dates, rather than individual wells, are the independent replicates.

analysis_auc_day <- auc_rep %>%
  ungroup() %>%
  mutate(
    Date = as.character(Date),
    RFP_Strain = as.character(RFP_Strain),
    RFP_Species6 = as.character(RFP_Species6),
    GFP_Strain = as.character(GFP_Strain)
  ) %>%
  filter(
    RFP_Species6 %in% rfp_order,
    GFP_Strain %in% gfp_order,
    is.finite(Normalized_AUC_RFP),
    is.finite(Normalized_AUC_GFP),
    Normalized_AUC_RFP > 0,
    Normalized_AUC_GFP > 0
  ) %>%
  group_by(Date, RFP_Strain, RFP_Species6, GFP_Strain) %>%
  summarise(
    log10_AUC_RFP = mean(log10(Normalized_AUC_RFP)),
    log10_AUC_GFP = mean(log10(Normalized_AUC_GFP)),
    n_tech = n(),
    .groups = "drop"
  ) %>%
  mutate(
    RFP_Species6 = factor(RFP_Species6, levels = rfp_order),
    GFP_Strain = factor(GFP_Strain, levels = gfp_order)
  )

# Check against the final accepted competition data.
if (
  nrow(analysis_auc_day) != 282L ||
  n_distinct(analysis_auc_day$RFP_Strain) != 15L ||
  nrow(distinct(analysis_auc_day, RFP_Strain, GFP_Strain)) != 90L ||
  any(!is.finite(analysis_auc_day$log10_AUC_RFP)) ||
  any(!is.finite(analysis_auc_day$log10_AUC_GFP))
) {
  stop(
    "Unexpected AUC input: expected 282 accepted date-level records, ",
    "15 RFP strains and 90 strain/competitor pairs."
  )
}

cat("\n================ FIGURE S2a INPUT CHECK ================\n")
print(
  analysis_auc_day %>%
    summarise(
      n_day_rows = n(),
      n_dates = n_distinct(Date),
      n_rfp_strains = n_distinct(RFP_Strain),
      n_strain_pairs = n_distinct(interaction(RFP_Strain, GFP_Strain))
    ),
  width = Inf
)
print(
  analysis_auc_day %>%
    count(RFP_Species6, GFP_Strain) %>%
    arrange(RFP_Species6, GFP_Strain),
  n = Inf, width = Inf
)

# Descriptive heatmap means

# Average date-level responses within each competitor and RFP group.
# Pf, Pu and Ps are pooled as Other; values are raw means, not EMMs.

make_raw_display_means <- function(dat, value_col, response_label) {
  
  focal_df <- dat %>%
    filter(RFP_Species6 %in% c("Ba", "Bb", "Bh")) %>%
    group_by(GFP_Strain, RFP_Species6) %>%
    summarise(
      estimate = mean(.data[[value_col]]),
      n_day_rows = n(),
      .groups = "drop"
    ) %>%
    transmute(
      Response = response_label,
      GFP_Strain,
      Group = as.character(RFP_Species6),
      estimate,
      n_day_rows
    )
  
  other_df <- dat %>%
    filter(RFP_Species6 %in% c("Pf", "Pu", "Ps")) %>%
    group_by(GFP_Strain) %>%
    summarise(
      estimate = mean(.data[[value_col]]),
      n_day_rows = n(),
      .groups = "drop"
    ) %>%
    transmute(
      Response = response_label,
      GFP_Strain,
      Group = "Other",
      estimate,
      n_day_rows
    )
  
  bind_rows(other_df, focal_df) %>%
    mutate(
      GFP_Strain = factor(as.character(GFP_Strain), levels = gfp_order),
      Group = factor(Group, levels = display_order),
      tile_label = sprintf("%.2f", estimate)
    ) %>%
    filter(!is.na(GFP_Strain), !is.na(Group)) %>%
    as_tibble()
}

rfp_cells <- make_raw_display_means(
  dat = analysis_auc_day,
  value_col = "log10_AUC_RFP",
  response_label = "Paraburkholderia response"
)

gfp_cells <- make_raw_display_means(
  dat = analysis_auc_day,
  value_col = "log10_AUC_GFP",
  response_label = "Competitor response"
)

auc_heatmap_cells <- bind_rows(rfp_cells, gfp_cells) %>% as_tibble()

# Expect 6 competitors x 4 groups for each fluorescence channel.
if (nrow(rfp_cells) != 24L || nrow(gfp_cells) != 24L ||
    any(!is.finite(auc_heatmap_cells$estimate))) {
  stop("Expected 24 valid cells for each heatmap (48 total).")
}

lim <- max(abs(auc_heatmap_cells$estimate))
lim <- max(0.6, ceiling(lim * 10) / 10)

breaks_use <- pretty(c(-lim, lim), n = 5)
breaks_use <- breaks_use[breaks_use >= -lim & breaks_use <= lim]

cat("\n================ FIGURE S2a HEATMAP CELLS ================\n")
print(
  auc_heatmap_cells %>% arrange(Response, GFP_Strain, Group),
  n = Inf, width = Inf
)

# Plot

base_heatmap_theme <- theme_minimal(base_size = 12) +
  theme(
    panel.grid = element_blank(),
    axis.title = element_blank(),
    axis.text.y = element_text(size = 11, colour = "black"),
    axis.text.x = element_text(
      size = 11, colour = "black", angle = 40, hjust = 1, vjust = 1
    ),
    plot.title = element_text(face = "bold", size = 13),
    legend.title = element_text(size = 11),
    legend.text = element_text(size = 10)
  )

make_heatmap <- function(cell_dat, plot_title) {
  ggplot(cell_dat, aes(x = Group, y = GFP_Strain, fill = estimate)) +
    geom_tile(colour = "white", linewidth = 0.9) +
    geom_text(aes(label = tile_label), size = 4.6, fontface = "bold") +
    scale_fill_gradient2(
      low = "#3B4CC0",
      mid = "white",
      high = "#B40426",
      midpoint = 0,
      limits = c(-lim, lim),
      breaks = breaks_use,
      name = expression(log[10] * "(normalized AUC)")
    ) +
    scale_x_discrete(labels = group_labels_plot, drop = FALSE) +
    scale_y_discrete(
      limits = rev(gfp_order),
      labels = competitor_labels[rev(gfp_order)],
      drop = FALSE
    ) +
    labs(title = plot_title) +
    coord_fixed() +
    base_heatmap_theme
}

p_rfp_auc_heatmap <- make_heatmap(
  cell_dat = rfp_cells,
  plot_title = "A. Paraburkholderia response"
)

p_gfp_auc_heatmap <- make_heatmap(
  cell_dat = gfp_cells,
  plot_title = "B. Competitor response"
)

final_mech_pub <- (p_rfp_auc_heatmap + p_gfp_auc_heatmap) +
  plot_layout(guides = "collect") +
  plot_annotation(
    title = "Responses relative to monoculture during competition",
    subtitle = paste0(
      "Positive values indicate performance above monoculture; ",
      "negative values indicate suppression below monoculture.\n",
      "Tiles show raw date-level means on the log10(normalized AUC) scale."
    ),
    theme = theme(
      plot.title = element_text(face = "bold", size = 16),
      plot.subtitle = element_text(size = 11)
    )
  ) &
  theme(legend.position = "right")

print(final_mech_pub)

# Optional export (off by default)

if (SAVE_FIGS2A) {
  if (!requireNamespace("svglite", quietly = TRUE)) {
    stop("Install 'svglite' before exporting SVG figures.")
  }
  
  dir.create(OUTPUT_DIR, recursive = TRUE, showWarnings = FALSE)
  ggsave(
    filename = file.path(OUTPUT_DIR, "Figure_S2a_AUC_heatmaps.svg"),
    plot = final_mech_pub,
    device = svglite::svglite,
    width = 12.5,
    height = 8,
    units = "in",
    bg = "white"
  )
}
